1	use std::env;
2	use std::io::Read;
3	use std::process::ExitCode;
4	
5	/// Authentication core shared by `sign` and `verify`.
6	///
7	/// This module owns everything about *computing* format-1 tags: key
8	/// validation and decoding, the canonical byte encoding of the authenticated
9	/// content, the HMAC-SHA256 computation itself, and constant-time tag
10	/// comparison. It knows nothing about command lines, JSON records, standard
11	/// output or exit codes — the subcommands own all of that presentation and
12	/// map these results to output lines and exit statuses.
13	mod auth {
14	    use hmac::{
15	        Hmac, Mac,
16	        digest::KeyInit,
17	    };
18	    use sha2::Sha256;
19	
20	    /// Record format version written by `sign` and required by `verify`.
21	    pub const FORMAT_VERSION: u32 = 1;
22	    /// Algorithm name written by `sign` and required by `verify`.
23	    pub const ALGORITHM: &str = "HMAC-SHA256";
24	    /// Domain separator that also records the format version, so tags computed
25	    /// by different versions of the encoding can never collide.
26	    const DOMAIN_SEPARATOR: &[u8] = b"authnote-sign-v1";
27	
28	    /// One computed authentication tag: a full HMAC-SHA256 output.
29	    pub type Tag = [u8; 32];
30	
31	    /// Shared key validation for `sign` and `verify`: non-empty even-length
32	    /// hex. The rejected value is never included in the message.
33	    pub fn validate_key_hex(key: &str) -> Result<(), String> {
34	        if key.is_empty() || key.len() % 2 != 0 || !key.bytes().all(|b| b.is_ascii_hexdigit()) {
35	            return Err("--key must be a non-empty, even-length hexadecimal string".to_string());
36	        }
37	        Ok(())
38	    }
39	
40	    /// Decode key text that has passed `validate_key_hex` into raw bytes.
41	    /// The bytes feed the MAC only; they never appear in any record.
42	    pub fn decode_key(hex: &str) -> Vec<u8> {
43	        decode_hex(hex).expect("key was validated as hex")
44	    }
45	
46	    /// Compute the format-1 authentication tag over the given content.
47	    ///
48	    /// Both `sign` (to emit a tag) and `verify` (to recompute the expected
49	    /// tag) go through this single path, so the two can never drift apart.
50	    pub fn compute_tag(key: &[u8], key_id: &str, key_version: u32, fields: &[String]) -> Tag {
51	        let message = encode_message(key_id, key_version, fields);
52	        let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(key)
53	            .expect("HMAC accepts keys of any length");
54	        mac.update(&message);
55	        mac.finalize().into_bytes().into()
56	    }
57	
58	    /// Compare a recomputed tag with the tag from a record, in constant time
59	    /// so a mismatch cannot be recovered one byte at a time through timing.
60	    pub fn tags_match(expected: &Tag, given: &[u8]) -> bool {
61	        if expected.len() != given.len() {
62	            return false;
63	        }
64	        let mut diff = 0u8;
65	        for (a, b) in expected.iter().zip(given.iter()) {
66	            diff |= a ^ b;
67	        }
68	        diff == 0
69	    }
70	
71	    /// Canonical byte encoding of the authenticated content.
72	    ///
73	    /// Layout (all integers big-endian, all text UTF-8, no trimming or escaping):
74	    ///   DOMAIN_SEPARATOR ("authnote-sign-v1", 16 ASCII bytes)
75	    ///   u64 length of key-id, then key-id bytes
76	    ///   u32 key version
77	    ///   u64 field count
78	    ///   for each field in order: u64 length of field, then field bytes
79	    ///
80	    /// Length prefixes make field boundaries unambiguous: ["ab","c"] and
81	    /// ["a","bc"] encode differently, as do zero fields and one empty field.
82	    fn encode_message(key_id: &str, key_version: u32, fields: &[String]) -> Vec<u8> {
83	        let mut out = Vec::new();
84	        out.extend_from_slice(DOMAIN_SEPARATOR);
85	        push_len_prefixed(&mut out, key_id.as_bytes());
86	        out.extend_from_slice(&key_version.to_be_bytes());
87	        out.extend_from_slice(&(fields.len() as u64).to_be_bytes());
88	        for field in fields {
89	            push_len_prefixed(&mut out, field.as_bytes());
90	        }
91	        out
92	    }
93	
94	    fn push_len_prefixed(out: &mut Vec<u8>, bytes: &[u8]) {
95	        out.extend_from_slice(&(bytes.len() as u64).to_be_bytes());
96	        out.extend_from_slice(bytes);
97	    }
98	
99	    pub fn decode_hex(s: &str) -> Result<Vec<u8>, String> {
100	        (0..s.len())
101	            .step_by(2)
102	            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
103	            .collect()
104	    }
105	
106	    pub fn hex_encode(bytes: &[u8]) -> String {
107	        bytes.iter().map(|b| format!("{b:02x}")).collect()
108	    }
109	}
110	
111	fn main() -> ExitCode {
112	    let args: Vec<String> = match decode_args() {
113	        Ok(args) => args,
114	        Err(msg) => {
115	            eprintln!("authnote: {msg}");
116	            return ExitCode::from(2);
117	        }
118	    };
119	    match args.first().map(String::as_str) {
120	        Some("--version") if args.len() == 1 => {
121	            println!("authnote 0.1.0");
122	            ExitCode::SUCCESS
123	        }
124	        Some("sign") => sign(&args[1..]),
125	        Some("verify") => verify(&args[1..]),
126	        _ => {
127	            eprintln!("Usage: authnote --version");
128	            eprintln!(
129	                "       authnote sign --key HEX --key-id ID --key-version N [--field TEXT]..."
130	            );
131	            eprintln!("       authnote verify --key HEX");
132	            ExitCode::from(2)
133	        }
134	    }
135	}
