137	/// Decode the process arguments (excluding the program name) as UTF-8 text.
138	///
139	/// `env::args()` panics on arguments that are not valid UTF-8; decoding via
140	/// `args_os()` lets us report the problem as an ordinary usage error instead.
141	/// The raw bytes are never printed: the message only states *that* an
142	/// argument could not be decoded, not what it contained.
143	fn decode_args() -> Result<Vec<String>, String> {
144	    let mut out = Vec::new();
145	    for (index, arg) in env::args_os().skip(1).enumerate() {
146	        match arg.into_string() {
147	            Ok(s) => out.push(s),
148	            Err(_) => {
149	                return Err(format!(
150	                    "argument {} is not valid UTF-8 text; all arguments must be decodable text",
151	                    index + 1
152	                ));
153	            }
154	        }
155	    }
156	    Ok(out)
157	}
