514	#[test]
515	fn sign_key_version_007_canonicalizes_but_record_007_is_corrupt() {
516	    // The command line and the record grammar differ on purpose: sign's
517	    // --key-version is decimal command-line text, so "007" means integer 7;
518	    // the emitted record must carry the canonical integer spelling 7 and then
519	    // verify normally.
520	    let out = run_sign(KV_KEY, KV_KID, "007", &[KV_FIELD]);
521	    assert_eq!(out.status.code(), Some(0));
522	    assert!(out.stderr.is_empty());
523	    let signed = String::from_utf8(out.stdout).unwrap();
524	    assert!(signed.contains("\"key_version\":7"), "record must carry integer 7: {signed}");
525	    assert!(!signed.contains("\"key_version\":007"), "record must not carry 007: {signed}");
526	    let rec = parse_single_record(signed.as_bytes());
527	    assert_eq!(rec.key_version, 7);
528	    assert_eq!(rec.tag, KV_TAG_V7, "007 must authenticate as integer 7");
529	
530	    // The produced record verifies as-is, and again when surrounded only by
531	    // legal JSON whitespace.
532	    let body = signed.trim_end_matches('\n');
533	    for input in [signed.as_bytes().to_vec(), format!(" \t\n{body}  \r\n").into_bytes()] {
534	        let out = run_verify(KV_KEY, &input);
535	        assert_eq!(out.status.code(), Some(0), "stderr={:?}", String::from_utf8_lossy(&out.stderr));
536	        assert_eq!(out.stdout, b"{\"valid\":true}\n");
537	        assert!(out.stderr.is_empty());
538	    }
539	
540	    // Rewriting the number INSIDE the record to 007 crosses the grammar line:
541	    // leading zeros are corrupt JSON, exit 2 (not a mismatch and not integer 7).
542	    let tampered = body.replace("\"key_version\":7", "\"key_version\":007");
543	    assert_ne!(tampered, body);
544	    let out = run_verify(KV_KEY, tampered.as_bytes());
545	    assert_eq!(out.status.code(), Some(2));
546	    assert!(out.stdout.is_empty());
547	    let stderr = String::from_utf8_lossy(&out.stderr);
548	    assert!(!stderr.contains(KV_KEY), "stderr echoed the key: {stderr}");
549	    assert!(!stderr.contains(KV_FIELD), "stderr echoed a field: {stderr}");
550	}
