1283	// ---------------------------------------------------------------------------
1284	// Option spelling: `--name value` vs `--name=value` (freely mixed).
1285	//
1286	// Every sign option accepts both spellings and they are the *same*
1287	// invocation: the same key, key id, version and in-order fields must produce a
1288	// byte-identical record and tag whether each option is written separated,
1289	// inline with '=', or alternating. Golden tags below are independently
1290	// computed with Python's hmac/hashlib/struct over the format-1 contract in
1291	// README.md, never taken from this crate's own HMAC code.
1292	// ---------------------------------------------------------------------------
1293	
1294	/// Assert that every argv spelling of one invocation exits 0 with empty
1295	/// stderr and byte-identical stdout, then parse and return the shared record
1296	/// together with its exact stdout bytes.
1297	fn expect_equivalent_spellings(label: &str, forms: &[&[&str]]) -> (Record, Vec<u8>) {
1298	    let mut stdout: Option<Vec<u8>> = None;
1299	    for (index, args) in forms.iter().enumerate() {
1300	        let out = run_sign_raw(args);
1301	        assert_eq!(
1302	            out.status.code(),
1303	            Some(0),
1304	            "{label} form {index}: expected exit 0, stderr={:?}",
1305	            String::from_utf8_lossy(&out.stderr)
1306	        );
1307	        assert!(
1308	            out.stderr.is_empty(),
1309	            "{label} form {index}: stderr must be empty, got {:?}",
1310	            String::from_utf8_lossy(&out.stderr)
1311	        );
1312	        if let Some(prev) = &stdout {
1313	            assert_eq!(
1314	                prev,
1315	                &out.stdout,
1316	                "{label} form {index}: the two spellings must produce byte-identical records"
1317	            );
1318	        } else {
1319	            stdout = Some(out.stdout);
1320	        }
1321	    }
1322	    let bytes = stdout.expect("at least one spelling must be provided");
1323	    (parse_single_record(&bytes), bytes)
1324	}
