1342	        "--key=00ff", "--key-id=id", "--key-version=1",
1343	        "--field=世界",
1344	        "--field=\n换行 ",
1345	        "--field= a=b=c ",
1346	        "--field=x",
1347	        "--field=x",
1348	        "--field=",
1349	    ];
1350	    let mixed: &[&str] = &[
1351	        "--key=00ff", "--key-id", "id", "--key-version=1",
1352	        "--field", "世界",
1353	        "--field=\n换行 ",
1354	        "--field", " a=b=c ",
1355	        "--field=x",
1356	        "--field", "x",
1357	        "--field=",
1358	    ];
1359	    let (rec, raw) =
1360	        expect_equivalent_spellings("all-four-options", &[separated, inline, mixed]);
1361	
1362	    // Independent Python golden over the format-1 encoding of these inputs.
1363	    assert_eq!(
1364	        rec.tag,
1365	        "711be5386282d260dc10332d4a7677e3af3906eeff7ae12b2d0fe7b25ea18f10"
1366	    );
1367	    assert_eq!(rec.key_id, "id");
1368	    assert_eq!(rec.key_version, 1);
1369	    assert_eq!(
1370	        rec.fields,
1371	        vec![
1372	            "世界".to_string(),
1373	            "\n换行 ".to_string(),
1374	            " a=b=c ".to_string(),
1375	            "x".to_string(),
1376	            "x".to_string(),
1377	            String::new(),
1378	        ]
1379	    );
1380	    // Mixing spellings neither reorders fields, merges the duplicate "x", nor
1381	    // drops the trailing empty field: all six survive in argv order.
1382	    assert_eq!(rec.fields.len(), 6);
1383	
1384	    // The whitespace and the embedded '=' survive on the wire untrimmed.
1385	    let text = String::from_utf8(raw).unwrap();
1386	    assert!(text.contains("\" a=b=c \""), "surrounding whitespace must be kept: {text}");
1387	
1388	    // The actual key feeds only the MAC; it is not a record value.
1389	    let mut strings = Vec::new();
1390	    rec.raw.strings(&mut strings);
1391	    assert!(
1392	        strings.iter().all(|s| s != "00ff"),
1393	        "the raw key must not appear as a record value: {strings:?}"
1394	    );
1395	}
