        "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b",
        "demo",
        "3",
        &["hello", "世界"],
        "e451500f028e969efb0d6fe533ab40a90d2e8267112cd5c95804d86f7f076d8f",
